// IPv4 subnet calculator in JavaScript
function ipToInt(ip) {
  return ip.split('.').reduce((acc, octet) => (acc << 8) | parseInt(octet, 10), 0) >>> 0;
}

function intToIp(int) {
  return [(int >>> 24) & 0xff, (int >>> 16) & 0xff, (int >>> 8) & 0xff, int & 0xff].join('.');
}

function subnetInfo(cidr) {
  const [ip, prefixStr] = cidr.split('/');
  const prefix = parseInt(prefixStr, 10);
  const mask = prefix === 0 ? 0 : (0xffffffff << (32 - prefix)) >>> 0;
  const ipInt = ipToInt(ip);
  const networkInt = (ipInt & mask) >>> 0;
  const broadcastInt = (networkInt | (~mask >>> 0)) >>> 0;
  const firstHost = networkInt + 1;
  const lastHost = broadcastInt - 1;
  const hostCount = Math.pow(2, 32 - prefix) - 2;

  return {
    network:    intToIp(networkInt),
    broadcast:  intToIp(broadcastInt),
    mask:       intToIp(mask),
    firstHost:  intToIp(firstHost),
    lastHost:   intToIp(lastHost),
    hostCount:  hostCount > 0 ? hostCount : 0
  };
}

console.log(subnetInfo('192.168.1.42/24'));
// { network: '192.168.1.0', broadcast: '192.168.1.255',
//   mask: '255.255.255.0', firstHost: '192.168.1.1',
//   lastHost: '192.168.1.254', hostCount: 254 }

console.log(subnetInfo('10.0.0.0/8'));
// { network: '10.0.0.0', broadcast: '10.255.255.255',
//   mask: '255.0.0.0', firstHost: '10.0.0.1',
//   lastHost: '10.255.255.254', hostCount: 16777214 }

// Check if two IPs are in the same subnet
function sameSubnet(ip1, ip2, prefix) {
  const mask = (0xffffffff << (32 - prefix)) >>> 0;
  return (ipToInt(ip1) & mask) === (ipToInt(ip2) & mask);
}

console.log(sameSubnet('192.168.1.5', '192.168.1.200', 24)); // true
console.log(sameSubnet('192.168.1.5', '192.168.2.5',   24)); // false

// ── Key address ranges ───────────────────────────────────────
const PRIVATE_RANGES = [
  { cidr: '10.0.0.0/8',      hosts: 16_777_214, use: 'Large private networks' },
  { cidr: '172.16.0.0/12',   hosts: 1_048_574,  use: 'Medium private networks' },
  { cidr: '192.168.0.0/16',  hosts: 65_534,     use: 'Home / small office' },
  { cidr: '127.0.0.0/8',     hosts: 0,          use: 'Loopback (localhost)' },
  { cidr: '169.254.0.0/16',  hosts: 65_534,     use: 'Link-local (APIPA, no DHCP)' },
];

// ── IPv4 vs IPv6 ─────────────────────────────────────────────
//  Property        │ IPv4                  │ IPv6
// ─────────────────┼───────────────────────┼──────────────────────
//  Address bits    │ 32                    │ 128
//  Notation        │ 192.168.1.1           │ 2001:db8::1
//  Address space   │ ~4.3 billion          │ ~3.4 × 10^38
//  Header size     │ 20 bytes (min)        │ 40 bytes (fixed)
//  NAT required    │ Yes (exhausted)       │ No (abundance)
//  Loopback        │ 127.0.0.1             │ ::1
//  Broadcast       │ Yes                   │ No (multicast instead)

// ── CIDR prefix → host count ─────────────────────────────────
for (const prefix of [8, 16, 24, 28, 30, 32]) {
  const hosts = prefix < 31 ? Math.pow(2, 32 - prefix) - 2 : (prefix === 31 ? 2 : 1);
  console.log(`/${prefix} → ${hosts.toLocaleString()} hosts`);
}
// /8  → 16,777,214 hosts
// /16 → 65,534 hosts
// /24 → 254 hosts
// /28 → 14 hosts
// /30 → 2 hosts  (point-to-point links)
// /32 → 1 host   (single host route)
